python
def frequencyFilesPositiveProofStrip(readings, k):
    a=readings
    out=[]
    counts={}
    for x in a: counts[x]=counts.get(x,0)+1
    for x in sorted(counts): out.append(counts[x])
    return [x for x in out if x>0]


java
class Solution {
  public int[] frequencyFilesPositiveProofStrip(int[] readings, int k) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {Map<Integer,Integer>counts=new TreeMap<>();for(int x:a)counts.merge(x,1,Integer::sum);out.addAll(counts.values());}
    return out.stream().filter(x->x>0).mapToInt(Integer::intValue).toArray();
  }
}
